import java.util.*;
import xinguan.platform.*;

final class IdentityPages extends PageLayout {
  IdentityPages(String version,AuthService.Session session){super(version,session);}
  String login(String message,String csrf){return page("统一登录","<div class=\"login-page\"><div class=\"login-brand\"><span class=\"brand-mark\">信</span><h1>智慧信管</h1></div><div class=\"login-card\"><h2>统一认证号登录</h2><p>使用管理员分配的账号和密码登录。</p>"+alert(message)+"<form method=\"post\" action=\"/login\">"+hidden("csrf",csrf)+"<label for=\"authNumber\">统一认证号</label><input id=\"authNumber\" name=\"authNumber\" type=\"text\" maxlength=\"20\" autocomplete=\"username\"><label for=\"password\">密码</label><input id=\"password\" name=\"password\" type=\"password\" maxlength=\"128\" autocomplete=\"current-password\"><button class=\"btn btn-primary btn-block\" type=\"submit\">登录</button></form><p class=\"field-note\">没有账号可<a href=\"/access/apply\">申请权限</a>。本系统暂未对接行内单点登录。</p></div></div>");}
  String password(String message){return page("修改密码",header()+"<div class=\"page-shell\"><section class=\"identity-card identity-narrow\"><h1>"+(currentSession.mustChangePassword?"首次登录，请修改初始密码":"修改密码")+"</h1><p>新密码需要 6～128 位，不能与当前密码相同。修改后需重新登录。</p>"+alert(message)+"<label>当前账号<strong class=\"identity-fixed\">"+e(currentSession.authNumber)+" · "+e(currentSession.actor.name())+"</strong></label><label for=\"currentPasswordMask\">当前密码（不可编辑）</label><input id=\"currentPasswordMask\" class=\"identity-readonly\" type=\"password\" value=\"********\" readonly=\"readonly\" disabled=\"disabled\" autocomplete=\"off\"><p class=\"field-note\">此处仅为固定掩码，不显示或回填真实密码。已通过本次登录验证身份，无需重复输入当前密码；登录超过 15 分钟需重新登录后再修改。</p><form method=\"post\" action=\"/account/password\">"+hidden("csrf",currentSession.csrf)+"<label>新密码<input type=\"password\" name=\"next\" maxlength=\"128\" autocomplete=\"new-password\"></label><label>确认新密码<input type=\"password\" name=\"confirm\" maxlength=\"128\" autocomplete=\"new-password\"></label><button class=\"btn btn-primary\" type=\"submit\">确认修改</button></form></section></div>");}
  String people(List<UserAccount> users,String message){
    StringBuilder b=new StringBuilder(header()).append("<div class=\"page-shell\"><div class=\"panel-head\"><h1>人员管理</h1><a class=\"btn btn-primary\" href=\"/people/new\">添加人员</a></div><p>仅显示你有权管理的人员。统一认证号不可重复；删除按停用处理，保留历史记录。</p>");
    if(message!=null&&!message.isBlank())b.append("<div class=\"alert alert-success\">").append(e(message)).append("</div>");
    b.append("<div class=\"table-scroll\"><table class=\"data-table\"><thead><tr><th>统一认证号</th><th>姓名</th><th>角色</th><th>机构</th><th>账号状态</th><th>操作</th></tr></thead><tbody>");
    for(UserAccount user:users){
      b.append("<tr><td>").append(e(user.authNumber())).append("</td><td>").append(e(user.name())).append("</td><td>").append(roleName(user.role())).append("</td><td>").append(e(Organizations.label(user.organizationId()))).append("</td><td>").append(user.active()?(user.mustChangePassword()?"待首次改密":"正常"):"已停用").append("</td><td class=\"people-actions\">");
      if(!currentSession.actor.userId().equals(user.id())&&AccessPolicy.canManage(currentSession.actor,user.role(),user.organizationId())){
        b.append("<a href=\"/people/edit?id=").append(u(user.id())).append("\">查看 / 修改 / 重置密码</a> <form class=\"inline-form\" method=\"post\" action=\"/people/initial-password\">").append(hidden("csrf",currentSession.csrf)).append(hidden("id",user.id())).append("<button class=\"link-button\" type=\"submit\">查看初始密码</button></form>");
        if(user.active())b.append(" ").append(deleteLink(user));
      }else b.append("当前账号");
      b.append("</td></tr>");
    }
    return page("人员管理",b.append("</tbody></table></div></div>").toString());
  }
  private String deleteLink(UserAccount user){return "<a class=\"btn btn-delete-person\" href=\"/people/delete?id="+u(user.id())+"\">删除人员</a>";}
  String deleteConfirmation(UserAccount user){
    StringBuilder b=new StringBuilder(header()).append("<div class=\"page-shell\"><section class=\"identity-card identity-narrow\"><h1>删除人员确认</h1><dl class=\"person-delete-summary\"><dt>姓名</dt><dd>").append(e(user.name())).append("</dd><dt>统一认证号</dt><dd>").append(e(user.authNumber())).append("</dd><dt>角色</dt><dd>").append(roleName(user.role())).append("</dd><dt>所属机构</dt><dd>").append(e(Organizations.label(user.organizationId()))).append("</dd></dl>");
    if(user.active()){
      b.append("<p>确认后该账号将停用，不能登录，当前登录会话也会失效。历史填报、审批及操作记录保留，统一认证号仍不可重复使用；如需恢复，可编辑原账号状态。</p><p>如果该人员还有未交接的申请或复核职责，系统会阻止删除，请先处理待办或安排替代人员。</p><form method=\"post\" action=\"/people/disable\">").append(hidden("csrf",currentSession.csrf)).append(hidden("id",user.id())).append(hidden("revision",""+user.revision())).append(hidden("confirmDisable","yes")).append("<button class=\"btn btn-delete-person\" type=\"submit\">确认删除（停用账号）</button> <a class=\"btn btn-light\" href=\"/people\">取消，返回人员管理</a></form>");
    }else b.append("<p>该人员已停用，无需重复删除。历史记录仍保留。</p><a class=\"btn btn-light\" href=\"/people\">返回人员管理</a>");
    return page("删除人员确认",b.append("</section></div>").toString());
  }
  String userForm(UserAccount user,Map<String,String> fields,String error){boolean creating=user==null;ActorContext a=currentSession.actor;String name=fields.getOrDefault("name",creating?"":user.name());String role=fields.getOrDefault("role",creating?(a.role()==Role.SUPER_ADMIN?"DIVISION_ADMIN":a.role()==Role.DIVISION_ADMIN?"BRANCH_ADMIN":"OPERATOR"):user.role().name());String org=fields.getOrDefault("organization",creating?(a.role()==Role.SUPER_ADMIN?Organizations.DIVISION:a.role()==Role.DIVISION_ADMIN?"WUJIN":a.organizationId()):user.organizationId());StringBuilder b=new StringBuilder(header()).append("<div class=\"page-shell\"><section class=\"identity-card identity-narrow\"><h1>").append(creating?"添加人员":"修改人员").append("</h1>").append(alert(error)).append("<form method=\"post\" action=\"").append(creating?"/people/create":"/people/update").append("\">").append(hidden("csrf",currentSession.csrf));if(!creating)b.append(hidden("id",user.id())).append(hidden("revision",""+user.revision()));b.append("<label>统一认证号");if(creating)b.append("<input name=\"authNumber\" value=\"").append(e(fields.getOrDefault("authNumber",""))).append("\" maxlength=\"20\" type=\"text\">");else b.append("<strong class=\"identity-fixed\">").append(e(user.authNumber())).append("</strong>");b.append("</label><label>姓名<input name=\"name\" value=\"").append(e(name)).append("\" maxlength=\"100\"></label><label>角色<select id=\"personRole\" name=\"role\">");for(Role r:Role.values()){boolean allowed=false;for(String candidate:Organizations.BRANCHES.keySet())allowed|=AccessPolicy.canManage(a,r,candidate);allowed|=AccessPolicy.canManage(a,r,Organizations.DIVISION);if(allowed)b.append(option(r.name(),roleName(r),role));}b.append("</select></label>").append(organizationFields(a,role,org));if(!creating)b.append("<label>状态<select name=\"active\">").append(option("true","正常",fields.getOrDefault("active",""+user.active()))).append(option("false","停用",fields.getOrDefault("active",""+user.active()))).append("</select></label>");b.append("<button class=\"btn btn-primary\" type=\"submit\">").append(creating?"添加并生成初始密码":"保存人员信息").append("</button> <a class=\"btn btn-light\" href=\"/people\">返回人员管理</a></form>");if(!creating){b.append("<hr><p>重置后旧密码失效，生成的新初始密码仅显示一次。账号原有登录将失效。</p><form method=\"post\" action=\"/people/reset-password\">").append(hidden("csrf",currentSession.csrf)).append(hidden("id",user.id())).append(hidden("revision",""+user.revision())).append("<label><input class=\"identity-check\" type=\"checkbox\" name=\"confirmReset\" value=\"yes\">确认重置该人员密码</label><button class=\"btn btn-light\" type=\"submit\">重置密码</button></form>");if(user.active())b.append("<hr><p>删除即停用账号，不删除历史业务和操作记录；可再次编辑恢复。</p><form method=\"post\" action=\"/people/disable\">").append(hidden("csrf",currentSession.csrf)).append(hidden("id",user.id())).append(hidden("revision",""+user.revision())).append("<label><input class=\"identity-check\" type=\"checkbox\" name=\"confirmDisable\" value=\"yes\">确认停用该人员</label><button class=\"btn btn-light\" type=\"submit\">删除（停用）</button></form>");}return page(creating?"添加人员":"修改人员",b.append("</section></div><script src=\"/assets/identity.js\"></script>").toString());}
  private String organizationFields(ActorContext actor,String role,String selected){
    boolean division=Role.DIVISION_ADMIN.name().equals(role);
    String branch=Organizations.BRANCHES.containsKey(selected)?selected:"";
    StringBuilder b=new StringBuilder("<div id=\"personOrganizationFields\"").append(division?" style=\"display:none\"":"").append("><label for=\"personOrganization\">所属支行</label><select id=\"personOrganization\" name=\"organization\">");
    b.append(option("","请选择支行",branch));
    for(var entry:Organizations.BRANCHES.entrySet())if(AccessPolicy.all(actor)||actor.organizationId().equals(entry.getKey()))b.append(option(entry.getKey(),entry.getValue(),branch));
    return b.append("</select></div><noscript><style type=\"text/css\">#personOrganizationFields{display:block!important}</style><p class=\"field-note\">分行管理员自动归属分行，无需选择支行；其他角色请选择所属支行。</p></noscript>").toString();
  }
  String created(PlatformStore.CreatedUser result){return page("初始密码",header()+"<div class=\"page-shell\"><section class=\"identity-card identity-narrow\"><h1>初始密码已生成</h1><p>人员："+e(result.user().name())+"</p><p>统一认证号："+e(result.user().authNumber())+"</p><p>角色："+roleName(result.user().role())+" · "+e(Organizations.label(result.user().organizationId()))+"</p><label>初始密码（本页显示）<input id=\"initialPassword\" class=\"initial-password\" readonly=\"readonly\" value=\""+e(result.initialPassword())+"\"></label><p>请通过单位认可的方式交给本人。本人首次修改前，授权管理员仍可在人员管理中查看；首次改密或停用后凭据立即失效且不可恢复，只能重新重置。</p><a class=\"btn btn-primary\" href=\"/people\">已记录，返回人员管理</a></section></div>");}
  String initialPassword(UserAccount user,String password){return page("查看初始密码",header()+"<div class=\"page-shell\"><section class=\"identity-card identity-narrow\"><h1>查看初始密码</h1><p>人员："+e(user.name())+" · "+e(user.authNumber())+"</p><label>尚未修改的临时密码<input id=\"initialPassword\" class=\"initial-password\" readonly=\"readonly\" value=\""+e(password)+"\"></label><p>该凭据仅在本人首次修改前可查看。查看行为已记入审计，不记录密码值；若已修改或无法恢复，请使用重置密码。</p><a class=\"btn btn-primary\" href=\"/people\">返回人员管理</a></section></div>");}
  private static String alert(String message){return message==null||message.isBlank()?"":"<div class=\"alert alert-error\">"+e(message)+"</div>";}
}
